//! `indicators::ProgressDisplay` -- a counter of completed work out of a total,
//! rendered as `"Progress: <pct>% (<current>/<total>)"`.

use std::fmt;

/// Number of fractional digits used for the percentage in [`ProgressDisplay::display`].
const PERCENT_PRECISION: usize = 1;

/// Tracks progress towards `total` and renders it as a one line summary.
///
/// Deliberately unclamped, matching the C++ original: `update`/`increment`
/// accept and report values below zero and above `total` (a current of 224 out
/// of 200 renders as `112.0%`), and the counter is a plain `int`, so it wraps
/// on overflow rather than panicking.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ProgressDisplay {
    current: i32,
    total: i32,
}

impl ProgressDisplay {
    /// Create a display for `total` units of work, starting at zero.
    pub fn new(total: i32) -> Self {
        ProgressDisplay { current: 0, total }
    }

    /// Set the completed count to `value`.
    pub fn update(&mut self, value: i32) {
        self.current = value;
    }

    /// Add `delta` to the completed count.
    pub fn increment(&mut self, delta: i32) {
        self.current = self.current.wrapping_add(delta);
    }

    /// The completed count.
    pub fn current(&self) -> i32 {
        self.current
    }

    /// The target count.
    pub fn total(&self) -> i32 {
        self.total
    }

    /// Completion as a percentage.
    ///
    /// Computed in `f32` to match the C++ `float` arithmetic: for large counts
    /// the reduced mantissa is visible in the output, e.g. a current of
    /// 2147483647 renders as `1073741824.0%` and not `1073741823.5%`.
    pub fn percentage(&self) -> f32 {
        self.current as f32 / self.total as f32 * 100.0
    }

    /// Render the progress line, e.g. `"Progress: 75.0% (150/200)"`.
    pub fn display(&self) -> String {
        format!(
            "Progress: {:.*}% ({}/{})",
            PERCENT_PRECISION,
            self.percentage(),
            self.current,
            self.total
        )
    }
}

impl fmt::Display for ProgressDisplay {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.display())
    }
}

