//! caller-chosen number of decimal places.

use std::fmt;

/// A fraction rendered as a percentage with fixed precision.
///
/// The value is held as an `f32`, matching the C++ `float` member, and scaled
/// by 100 in `f32` before formatting.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Percentage {
    value: f32,
    precision: usize,
}

impl Percentage {
    /// Wrap `value` (a fraction, so `0.15` means 15%) for display with
    /// `precision` digits after the decimal point.
    pub fn new(value: f32, precision: usize) -> Self {
        Percentage { value, precision }
    }

    /// The underlying fraction.
    pub fn value(&self) -> f32 {
        self.value
    }

    /// The number of fractional digits used when formatting.
    pub fn precision(&self) -> usize {
        self.precision
    }

    /// The fraction scaled to a percentage.
    pub fn percent(&self) -> f32 {
        self.value * 100.0
    }

    /// Render as a percentage string, e.g. `"35.00%"` for `(0.35, 2)`.
    pub fn str(&self) -> String {
        format!("{:.*}%", self.precision, self.percent())
    }
}

impl fmt::Display for Percentage {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.str())
    }
}

