//! A faithful port of `std::stoi`.
//!
//! `std::stoi(s)` is specified as `strtol(s.c_str(), &end, 10)` plus two range
//! checks, which gives it a handful of behaviours that `str::parse::<i32>()`
//! does not share and that the original binary is observably sensitive to:
//!
//! * leading whitespace is skipped (`"  42  "` -> `42`),
//! * a leading `+` is accepted (`"+7"` -> `7`),
//! * parsing stops at the first character that is not a decimal digit, and the
//!   remainder is silently discarded (`"12abc"` -> `12`, `"0x10"` -> `0`,
//!   `"6.9"` -> `6`),
//! * no digits at all throws `std::invalid_argument`,
//! * a value outside `int` range throws `std::out_of_range`.

use std::process;

/// The two exception types `std::stoi` can throw. Both report `"stoi"` from
/// `what()`, which is what the uncaught-exception handler prints.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StoiError {
    /// `std::invalid_argument`: no digits could be consumed.
    InvalidArgument,
    /// `std::out_of_range`: the digits denote a value outside `int`.
    OutOfRange,
}

impl StoiError {
    /// The fully qualified name of the C++ exception class.
    pub fn exception_name(self) -> &'static str {
        match self {
            StoiError::InvalidArgument => "std::invalid_argument",
            StoiError::OutOfRange => "std::out_of_range",
        }
    }

    /// The string returned by the exception's `what()` member.
    pub fn what(self) -> &'static str {
        "stoi"
    }

    /// Reproduce libstdc++'s uncaught-exception behaviour: the verbose
    /// terminate handler writes a two line report to stderr, then `abort()`
    /// raises `SIGABRT` (exit status 134 as seen by a shell).
    pub fn terminate(self) -> ! {
        eprintln!(
            "terminate called after throwing an instance of '{}'",
            self.exception_name()
        );
        eprintln!("  what():  {}", self.what());
        process::abort();
    }
}

/// `true` for the characters `std::isspace` accepts in the C locale.
fn is_space(c: u8) -> bool {
    matches!(c, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Convert the leading decimal integer in `text` the way `std::stoi` does.
pub fn stoi(text: &str) -> Result<i32, StoiError> {
    let bytes = text.as_bytes();
    let mut i = 0;

    while i < bytes.len() && is_space(bytes[i]) {
        i += 1;
    }

    let negative = match bytes.get(i) {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    // `strtol` requires at least one digit after the optional sign, otherwise
    // no conversion is performed at all.
    let digits_start = i;
    // Accumulate in i64 and saturate: any overflow of `long` and any value
    // outside `int` both surface as std::out_of_range, so the exact magnitude
    // beyond the i32 bounds is irrelevant.
    let mut value: i64 = 0;
    while let Some(&c) = bytes.get(i) {
        if !c.is_ascii_digit() {
            break;
        }
        let digit = i64::from(c - b'0');
        value = value
            .saturating_mul(10)
            .saturating_add(if negative { -digit } else { digit });
        i += 1;
    }

    if i == digits_start {
        return Err(StoiError::InvalidArgument);
    }

    i32::try_from(value).map_err(|_| StoiError::OutOfRange)
}

/// Convenience wrapper mirroring an unguarded `std::stoi` call in `main`:
/// a thrown exception escapes and terminates the process.
pub fn stoi_or_terminate(text: &str) -> i32 {
    match stoi(text) {
        Ok(value) => value,
        Err(error) => error.terminate(),
    }
}

